"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["9133"],{2896(e,n,s){s.r(n),s.d(n,{metadata:()=>t,default:()=>u,frontMatter:()=>r,contentTitle:()=>l,toc:()=>h,assets:()=>d});var t=JSON.parse('{"id":"m8-config-rbac-microservices/lesson-2-microservices-outlook","title":"Lesson 2: The Microservices Outlook","description":"You have spent eight modules building one small application. It started in M1 as containers on a flat","source":"@site/docs/m8-config-rbac-microservices/lesson-2-microservices-outlook.md","sourceDirName":"m8-config-rbac-microservices","slug":"/m8-config-rbac-microservices/lesson-2-microservices-outlook","permalink":"/k8s-distributed-systems/docs/m8-config-rbac-microservices/lesson-2-microservices-outlook","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":2,"frontMatter":{"sidebar_position":2,"title":"Lesson 2: The Microservices Outlook"},"sidebar":"courseSidebar","previous":{"title":"Lesson 1: Configuration & Access Control","permalink":"/k8s-distributed-systems/docs/m8-config-rbac-microservices/lesson-1-config-access-control"},"next":{"title":"Lab: Config, RBAC & NetworkPolicy","permalink":"/k8s-distributed-systems/docs/m8-config-rbac-microservices/lab"}}'),o=s(4848),i=s(8453),a=s(7684);let r={sidebar_position:2,title:"Lesson 2: The Microservices Outlook"},l="The Microservices Outlook",d={},h=[{value:"The analogy: a department store versus a shopping district",id:"the-analogy-a-department-store-versus-a-shopping-district",level:2},{value:"Monolith versus microservices, honestly",id:"monolith-versus-microservices-honestly",level:2},{value:"Twelve-factor: the principles under the patterns",id:"twelve-factor-the-principles-under-the-patterns",level:2},{value:"What you actually built: the patterns, mapped",id:"what-you-actually-built-the-patterns-mapped",level:2},{value:"Common pitfalls migrating from a monolith",id:"common-pitfalls-migrating-from-a-monolith",level:2},{value:"Program wrap-up",id:"program-wrap-up",level:2}];function c(e){let n={code:"code",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",p:"p",strong:"strong",ul:"ul",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(n.header,{children:(0,o.jsx)(n.h1,{id:"the-microservices-outlook",children:"The Microservices Outlook"})}),"\n",(0,o.jsx)(a.A,{src:"decks/m8-microservices-outlook.html",title:"M8 \u2014 The Microservices Outlook"}),"\n",(0,o.jsx)(n.p,{children:"You have spent eight modules building one small application. It started in M1 as containers on a flat\nDocker network, and it ends here as a set of independently deployed, independently scaled, network-isolated\nservices with a real front door and hardened access control. Along the way nobody stopped to say the word\nthat describes what you built. This lesson does. It names the architecture, is honest about what it costs,\nand maps every pattern back to the module where you already implemented it."}),"\n",(0,o.jsxs)(n.p,{children:["There is no lab here. This is the part where you step back from ",(0,o.jsx)(n.code,{children:"kubectl"})," and see the shape of the whole\nthing."]}),"\n",(0,o.jsx)(n.h2,{id:"the-analogy-a-department-store-versus-a-shopping-district",children:"The analogy: a department store versus a shopping district"}),"\n",(0,o.jsx)(n.p,{children:"Picture two ways to run a retail business."}),"\n",(0,o.jsxs)(n.p,{children:["The first is one big ",(0,o.jsx)(n.strong,{children:"department store"}),". Everything under one roof \u2014 homeware, candles, kitchenware,\ncheckout \u2014 all in the same building, sharing the same walls, the same power, the same front door. Walking\nfrom one department to another is instant; you just cross the aisle. There is one building to heat, one\nalarm system, one lease. For a small or medium business this is wonderfully simple, and for a long time it\nis exactly the right choice."]}),"\n",(0,o.jsx)(n.p,{children:"But it has failure modes baked into the building. A burst pipe in kitchenware floods the whole store and\neverything closes. To expand the candle department you renovate the shared building, disrupting every other\ndepartment while you do. And you cannot give the busy candle counter more floor space without taking it\nfrom homeware, because they share one floor. Everything is coupled because everything is under one roof."}),"\n",(0,o.jsxs)(n.p,{children:["The second is a ",(0,o.jsx)(n.strong,{children:"shopping district"}),": separate shops along a street, each in its own building. The candle\nshop, the homeware shop, the kitchenware shop \u2014 each with its own door, its own staff, its own opening\nhours. Now a fire in one shop does not close the others. The candle shop can expand, or rebuild, or restock\novernight without touching its neighbours. A popular shop can take a bigger unit while the quiet one stays\nsmall. Each shop can be run by a different team who never coordinate a shared renovation."]}),"\n",(0,o.jsxs)(n.p,{children:["The cost is just as real. Customers now walk ",(0,o.jsx)(n.strong,{children:"between"})," shops, across streets, and those streets have to\nexist and be maintained. You need ",(0,o.jsx)(n.strong,{children:"signage"})," so people find the right shop, ",(0,o.jsx)(n.strong,{children:"traffic control"})," at the\nmain entrance to the district, and someone responsible for the roads themselves. A single building had none\nof that overhead; a district lives or dies on it."]}),"\n",(0,o.jsxs)(n.p,{children:["The department store is a ",(0,o.jsx)(n.strong,{children:"monolith"}),". The shopping district is ",(0,o.jsx)(n.strong,{children:"microservices"}),". And the streets, the\nsignage, and the traffic control are not incidental \u2014 they are Kubernetes. Most of what you learned in this\ncourse was how to build and run the roads between the shops."]}),"\n",(0,o.jsx)(n.h2,{id:"monolith-versus-microservices-honestly",children:"Monolith versus microservices, honestly"}),"\n",(0,o.jsxs)(n.p,{children:["A ",(0,o.jsx)(n.strong,{children:"monolith"})," is one deployable unit. All the code \u2014 every feature, every module \u2014 builds into one\nartifact, runs as one process (or identical copies of it), and ships as one release. This is not a slur.\nMonoliths are simpler to build, simpler to test end to end, simpler to deploy, and faster at internal calls\nbecause a call from one module to another is a function call, not a network round trip. For a single team\nand a moderate codebase, a monolith is very often the ",(0,o.jsx)(n.em,{children:"correct"})," choice, and starting with one is sound\nadvice."]}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Microservices"})," split that one unit into many small services, each owning one capability, each deployed\nand scaled on its own, each talking to the others over the network. What you gain is real:"]}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Independent deployment."})," Ship the backend without redeploying the frontend. A change to one service\nis a small, contained release, not a whole-system event."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Independent scaling."})," Give the busy service more replicas without paying to scale the quiet ones. You\nscaled the Fernwood backend on CPU in M5 while the frontend sat still."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Independent failure."})," One service crashing does not take the others' processes down with it. Fernwood\nwas built to degrade \u2014 the frontend still renders when the backend is unreachable."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Team autonomy and technology fit."})," Different teams own different services and can even use different\nlanguages. Fernwood is Node, Python, and Java behind one front door, and none of the tiers cares."]}),"\n"]}),"\n",(0,o.jsx)(n.p,{children:"What it costs is just as real, and pretending otherwise is how migrations fail:"}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"The network is now in the middle of everything."})," A function call that never failed becomes a network\ncall that can time out, arrive twice, or vanish. Every call between services is a new failure mode."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Operational overhead multiplies."})," One service was one thing to deploy, monitor, and secure. Ten\nservices are ten of each \u2014 which is precisely why you needed orchestration, service discovery, ingress,\nand policy. Kubernetes is not overhead you chose for fun; it is the tax microservices levy."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Debugging spans processes."}),' A single request now crosses several services, and "why was this slow"\nbecomes a question you cannot answer by reading one log file.']}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Data is harder."})," One shared database is easy to reason about; data spread across services is not, and\nkeeping it consistent across service boundaries is one of the genuinely hard problems in the field."]}),"\n"]}),"\n",(0,o.jsxs)(n.p,{children:["The honest summary: microservices trade ",(0,o.jsx)(n.strong,{children:"internal simplicity for operational complexity"}),", and you take\nthat trade when the benefits \u2014 independent scaling, deployment, and team autonomy \u2014 are worth more to you\nthan the simplicity you give up. That is an organizational judgment as much as a technical one."]}),"\n",(0,o.jsx)(n.h2,{id:"twelve-factor-the-principles-under-the-patterns",children:"Twelve-factor: the principles under the patterns"}),"\n",(0,o.jsxs)(n.p,{children:['Long before "microservices" was a common word, a set of principles called the ',(0,o.jsx)(n.strong,{children:"twelve-factor app"}),"\ndescribed how to build a service that behaves well when it is deployed, scaled, and operated by a platform\nlike Kubernetes. You did not read the list first and then build to it \u2014 but you implemented several of its\nfactors directly, which is the best way to understand them."]}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Factor III \u2014 Config in the environment."})," This is exactly what you did in Lesson 1: the backend's\ndatabase settings moved out of the image and the manifest into a ConfigMap and a Secret, injected as\nenvironment variables. The image is built once and configured per environment from outside. That factor\nis why the same ",(0,o.jsx)(n.code,{children:"fernwood-backend"})," image runs against any database without a rebuild."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Factor VI \u2014 Processes are stateless."})," The Fernwood frontend and backend hold no durable state between\nrequests. That is what let you run three frontend replicas behind one Service in M4 and scale the backend\nup and down in M5 \u2014 any replica can serve any request because none of them is special. Statelessness is\nwhat makes horizontal scaling possible at all."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Factor IV \u2014 Backing services are attached resources."})," Postgres is not part of the backend; it is a\nresource the backend reaches over the network by name, through a Service (M4) and a StatefulSet (M6).\nSwap the database host in the ConfigMap and the backend attaches to a different one. The database is a\nplug-in dependency, not a built-in."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Factor V \u2014 Strictly separate build, release, run."})," Your image is the build; the image plus its\nConfigMap and Secret is the release; the running Pod is the run. Because config is separate, one build\nbecomes many releases, and a rollback (M5) is just running a previous release again."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Factor IX \u2014 Disposability."})," Pods start fast and can be killed at any moment. Readiness and liveness\nprobes (M3) and rolling updates (M5) all assume a Pod is disposable and replaceable, which is what makes\nself-healing and zero-downtime rollout work."]}),"\n"]}),"\n",(0,o.jsx)(n.p,{children:"The pattern here is that twelve-factor is not a checklist you bolt on at the end. It is the set of\nassumptions that let a platform run your service well \u2014 and building Fernwood on Kubernetes pushed you into\nfollowing it whether you named it or not."}),"\n",(0,o.jsx)(n.h2,{id:"what-you-actually-built-the-patterns-mapped",children:"What you actually built: the patterns, mapped"}),"\n",(0,o.jsx)(n.p,{children:"Here is the payoff. Every core microservices pattern has a name in the industry, and you already\nimplemented each one in a specific module. This is the whole course, restated as architecture."}),"\n",(0,o.jsx)(n.mermaid,{value:"flowchart TD\n  subgraph outside [Outside]\n    U[Client]\n  end\n  U --\x3e IN[Ingress / Envoy \u2014 M7<br/>the district's main gate]\n  IN --\x3e FE[frontend service \u2014 M4/M5]\n  FE --\x3e|by DNS name| BE[backend service \u2014 M4/M5]\n  BE --\x3e|by DNS name| DB[(Postgres \u2014 M6<br/>durable state)]\n  SD[cluster DNS + Services \u2014 M4<br/>service discovery] -.resolves.-> FE\n  SD -.resolves.-> BE\n  SD -.resolves.-> DB"}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Service discovery"})," \u2014 how one service finds another without hardcoded addresses. In a shopping district\nthis is the signage. You built it in ",(0,o.jsx)(n.strong,{children:"M4"}),": cluster DNS plus Services mean the backend reaches the\ndatabase as ",(0,o.jsx)(n.code,{children:"db-0.db.fernwood.svc.cluster.local"})," and the frontend reaches the backend as ",(0,o.jsx)(n.code,{children:"backend"}),", by\nname, no IP address anywhere. Pods come and go, IPs change, and the names keep resolving. That is the\npattern that makes independent services findable."]}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"API gateway versus Ingress"})," \u2014 the district's main gate, and a distinction worth getting right. In\n",(0,o.jsx)(n.strong,{children:"M7"})," you put Envoy in front of the app and routed by hostname and path. That is ",(0,o.jsx)(n.strong,{children:"Ingress"}),": its job is\nrouting \u2014 get the request to the right Service. An ",(0,o.jsx)(n.strong,{children:"API gateway"})," is a broader idea. A true gateway\ntypically does more than route: it authenticates callers, enforces rate limits, transforms requests and\nresponses, and sometimes aggregates several backend calls into one. Ingress is primarily the routing slice\nof that job. Envoy, the data plane you ran, is powerful enough to ",(0,o.jsx)(n.em,{children:"do"})," full gateway work and is the engine\ninside many commercial API gateways \u2014 but what you configured in M7 was routing, not a full gateway. Knowing\nthe difference keeps you honest: you built the front gate; a gateway also frisks and directs everyone who\ncomes through it."]}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Resilience"})," \u2014 staying up through change and failure. Two modules built this. ",(0,o.jsx)(n.strong,{children:"M5"})," gave you rolling\nupdates (ship a new version with no downtime), rollbacks (undo a bad release in one command), and the\nHorizontalPodAutoscaler (add replicas under load, remove them after). ",(0,o.jsx)(n.strong,{children:"M6"})," gave you durable state: the\nPostgres StatefulSet with a PersistentVolumeClaim, so the database's data outlives any Pod. Together they\nare the difference between a system that survives a deploy, a traffic spike, and a Pod restart, and one that\nfalls over at the first disturbance."]}),"\n",(0,o.jsxs)(n.p,{children:["And ",(0,o.jsx)(n.strong,{children:"isolation and access control"})," \u2014 this very module. NetworkPolicy walled the shops off from each other\nexcept on the paths that should exist; RBAC and Service Accounts decided who may touch what; ConfigMaps and\nSecrets separated configuration from code. A shopping district with no locks on the doors and no rules about\nwho can enter the stockroom is not one you would run a real business in."]}),"\n",(0,o.jsx)(n.h2,{id:"common-pitfalls-migrating-from-a-monolith",children:"Common pitfalls migrating from a monolith"}),"\n",(0,o.jsxs)(n.p,{children:["If you take one warning from this lesson, take this: ",(0,o.jsx)(n.strong,{children:"most microservices pain comes from splitting too\nearly, too finely, or along the wrong lines."})," The failures repeat:"]}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"The distributed monolith."})," You split the code into services, but they are so tightly coupled that you\ncan never deploy one without deploying the others in lockstep. You now have all the network cost of\nmicroservices and none of the independence. This is the most common bad outcome, and it comes from\nsplitting along technical layers instead of business capabilities."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Splitting before you understand the domain."})," Service boundaries are expensive to move once data and\nteams have formed around them. Drawing them before you know where the real seams are locks in the wrong\nlines. Many strong teams deliberately start with a monolith and split only once the seams are obvious."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Ignoring the network's new failure modes."})," Every inter-service call can fail, and a design that\nassumes calls always succeed will cascade one service's outage into a whole-system one. Fernwood's\ngraceful degradation \u2014 the frontend still working when the backend is down \u2014 is the small version of the\ndiscipline this demands everywhere."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Underestimating the operational bill."})," Ten services need ten times the deployment, monitoring,\nlogging, and security work of one. If you are not ready to run that platform, the split will bury you.\nThis entire course was, in effect, the operational bill made concrete."]}),"\n"]}),"\n",(0,o.jsx)(n.p,{children:"None of these is a reason never to use microservices. They are reasons to split deliberately, along\nbusiness capabilities, when the benefits are real \u2014 and to keep each service as independently deployable as\nthe department-store-to-district move promises."}),"\n",(0,o.jsx)(n.h2,{id:"program-wrap-up",children:"Program wrap-up"}),"\n",(0,o.jsxs)(n.p,{children:["Look back at the whole arc. In ",(0,o.jsx)(n.strong,{children:"M1"})," you started with distributed-systems fundamentals and a flat Docker\nnetwork. ",(0,o.jsx)(n.strong,{children:"M2"})," packaged and ran the app with Docker and Compose on a single host. ",(0,o.jsx)(n.strong,{children:"M3"})," moved it onto\nKubernetes as Pods, and ",(0,o.jsx)(n.strong,{children:"M4"})," organized and connected it with namespaces, ReplicaSets, and Services. ",(0,o.jsx)(n.strong,{children:"M5"}),"\nmade releases safe with Deployments, rollbacks, and autoscaling. ",(0,o.jsx)(n.strong,{children:"M6"})," gave it durable state with a\nStatefulSet and PersistentVolumes. ",(0,o.jsx)(n.strong,{children:"M7"})," opened a real front door with Envoy-based Ingress. And ",(0,o.jsx)(n.strong,{children:"M8"}),"\nhardened it \u2014 external configuration, RBAC, and NetworkPolicy \u2014 then named the whole thing."]}),"\n",(0,o.jsx)(n.p,{children:"What you built is one coherent system: Fernwood Goods, taken from three containers on one machine to a\nhardened, self-healing, independently scalable set of services on a real cluster \u2014 the same journey a\nproduction application makes. Every pattern you would meet on the job, you have now implemented at least\nonce with your own hands."}),"\n",(0,o.jsxs)(n.p,{children:["Where you go next is not new syntax; it is depth in the operational disciplines this course kept touching.\nThe natural continuations are observability (turning the logs, metrics, and probes you already used into a\nsystem that tells you ",(0,o.jsx)(n.em,{children:"why"})," a request was slow), delivery automation (turning the manual ",(0,o.jsx)(n.code,{children:"kubectl apply"}),"\ninto a pipeline), and, as a system grows past what plain Services and Ingress can express, a service mesh\n(pushing retries, timeouts, and mutual TLS down into the platform). Each of those builds directly on what\nyou have here. You already have the foundation they stand on \u2014 you built it, module by module, on Fernwood."]})]})}function u(e={}){let{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}},7684(e,n,s){s.d(n,{A:()=>i});var t=s(4848);s(6540);var o=s(6497);function i({src:e,title:n="Slides"}){let s=(0,o.Ay)(e);return(0,t.jsxs)("div",{className:"deck_nWXz",children:[(0,t.jsxs)("div",{className:"bar_dOoE",children:[(0,t.jsxs)("span",{className:"label_ZSLR",children:["\u25B6 ",n]}),(0,t.jsx)("a",{className:"full_PrDQ",href:s,target:"_blank",rel:"noopener noreferrer",children:"Open fullscreen \u2197"})]}),(0,t.jsx)("div",{className:"frame_M4DO",children:(0,t.jsx)("iframe",{src:s,title:n,loading:"lazy",allowFullScreen:!0})})]})}},8453(e,n,s){s.d(n,{R:()=>a,x:()=>r});var t=s(6540);let o={},i=t.createContext(o);function a(e){let n=t.useContext(i);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:a(e.components),t.createElement(i.Provider,{value:n},e.children)}}}]);